sys_script_include.script:
var ShozokuInfoAPI = Class.create();
ShozokuInfoAPI.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getYakuiAndBumon: function() {
        var shozokuId = this.getParameter('sysparm_shozoku');
        var result = {
            yakui: '',
            bumon: '',
            kinmuti: '',
            tyokkan: ''
        };

        if (!shozokuId) return JSON.stringify(result);

        var gr = new GlideRecord('x_1882833_organi_0_shozoku');
        if (gr.get(shozokuId)) {
            result.yakui = gr.getValue('yakui') || '';
            result.bumon = gr.getValue('bumon') || '';
            result.kinmuti = gr.getValue('kinmuti') || '';
            result.tyokkan = gr.getValue('tyokkan') || '';
        }
        return JSON.stringify(result);
    },

    addMeisai: function() {

        var parentTable = this.getParameter('sysparm_parent_table');
        var parentSysId = this.getParameter('sysparm_parent_sys_id');

        var gr = new GlideRecord(parentTable);
        if (gr.get(parentSysId)) {

            var gr2 = new GlideRecord('x_1882833_organi_0_meisai');
			gr2.initialize();

            gr2.sinsei_number = parentSysId;

            if (gr.sinsei_shubetu == 1) {
                gr2.type = "gen";
            } else {
                gr2.type = "exe";
            }

            gr2.insert();
        }

    },

    addFukusuu: function() {
        var parentTable = this.getParameter('sysparm_parent_table');
        var parentSysId = this.getParameter('sysparm_parent_sys_id');

        var gr = new GlideRecord(parentTable);
        if (gr.get(parentSysId)) {
            var type = gr.sinsei_shubetu;
            if (type == 1) {
                type = 'gen';
            } else {
                type = 'exe';
            }

            var url = 'https://dev182911.service-now.com/now/nav/ui/classic/params/target/x_1882833_organi_0_meisai.do%3Ffukusuu_flg%3Dtrue%26num%3D' + parentSysId + '%26type%3D' + type;

            return url;
        }
    },

    isPublic: function() {
        return true;
    },

    type: 'ShozokuInfoAPI'
});
